package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;
/** Independent evidence store. Web text is data, never executable instructions or model training. */
final class ResearchStore{
 static final int MAX_DOCS=80,MAX_TOPICS=8;static final long DAY=86400000L;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-research",0);}
 static JSONArray array(Context c,String key){try{return new JSONArray(prefs(c).getString(key,"[]"));}catch(Exception e){return new JSONArray();}}
 static synchronized void documents(Context c,List<ResearchWeb.Doc> docs)throws Exception{JSONArray old=array(c,"docs"),next=new JSONArray();Set<String> urls=new HashSet<>();for(ResearchWeb.Doc d:docs)if(next.length()<MAX_DOCS&&!d.text.isEmpty()&&urls.add(d.url))next.put(d.json());for(int i=0;i<old.length()&&next.length()<MAX_DOCS;i++){JSONObject d=old.getJSONObject(i);if(urls.add(d.optString("url")))next.put(d);}if(!prefs(c).edit().putString("docs",next.toString()).commit())throw new java.io.IOException("No pude guardar las fuentes.");}
 static List<ResearchWeb.Doc> search(Context c,String query)throws Exception{JSONArray rows=array(c,"docs");List<ResearchWeb.Doc> all=new ArrayList<>();for(int i=0;i<rows.length();i++){ResearchWeb.Doc d=ResearchWeb.Doc.read(rows.getJSONObject(i));if(ResearchAnswer.score(query,d.title+" "+d.text)>0)all.add(d);}Collections.sort(all,(a,b)->Double.compare(ResearchAnswer.score(query,b.title+" "+b.text),ResearchAnswer.score(query,a.title+" "+a.text)));return new ArrayList<>(all.subList(0,Math.min(5,all.size())));}
 static synchronized void follow(Context c,String topic)throws Exception{topic=ResearchConversation.cleanQuery(topic);if(topic.length()<3)throw new java.io.IOException("Elegí un tema de al menos tres caracteres.");JSONArray rows=array(c,"topics");for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getString("query").equalsIgnoreCase(topic))return;if(rows.length()>=MAX_TOPICS)throw new java.io.IOException("Ya hay ocho temas. Usá ‘deja de aprender sobre …’ para quitar uno.");rows.put(new JSONObject().put("query",topic).put("checked",0).put("status","Pendiente"));if(!prefs(c).edit().putString("topics",rows.toString()).commit())throw new java.io.IOException("No pude guardar el tema.");}
 static synchronized boolean unfollow(Context c,String topic)throws Exception{JSONArray old=array(c,"topics"),next=new JSONArray();boolean found=false;for(int i=0;i<old.length();i++){JSONObject row=old.getJSONObject(i);if(ChatLanguage.normalize(row.getString("query")).equals(ChatLanguage.normalize(topic)))found=true;else next.put(row);}if(found&&!prefs(c).edit().putString("topics",next.toString()).commit())throw new java.io.IOException("No pude quitar el tema.");return found;}
 static boolean following(Context c,String query){JSONArray rows=array(c,"topics");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&row.optString("query").equals(query))return true;}return false;}
 static synchronized String due(Context c){JSONArray rows=array(c,"topics");long oldest=Long.MAX_VALUE;String query="";for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&row.optLong("checked")<oldest){oldest=row.optLong("checked");query=row.optString("query");}}return query;}
 static synchronized void checked(Context c,String topic,String status)throws Exception{JSONArray rows=array(c,"topics");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.getString("query").equals(topic))row.put("checked",System.currentTimeMillis()).put("status",status);}if(!prefs(c).edit().putString("topics",rows.toString()).putLong("lastRun",System.currentTimeMillis()).commit())throw new java.io.IOException("No pude guardar el estado de actualización.");}
 static String status(Context c){StringBuilder b=new StringBuilder("Biblioteca web: "+array(c,"docs").length()+" fuentes.\nActualización periódica: "+(prefs(c).getBoolean("enabled",true)?"activada":"pausada")+".\nRed de fondo: "+(prefs(c).getBoolean("wifi",true)?"sin medición (normalmente Wi-Fi)":"cualquier conexión")+".\n");JSONArray rows=array(c,"topics");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null)b.append("\n• ").append(row.optString("query")).append(" — ").append(row.optString("status")).append(row.optLong("checked")==0?"":" · "+ResearchAnswer.date(row.optLong("checked")));}if(rows.length()==0)b.append("\nAgregá temas con ‘aprende sobre animación’.");b.append("\nSeguimiento de preguntas nuevas: ").append(prefs(c).getBoolean("followQueries",true)?"automático (hasta ocho temas)":"solo al pedir aprende sobre");b.append("\nProgramación: ").append(prefs(c).getString("schedule","Pendiente de registrar en Android")).append("\n").append(prefs(c).getString("lastError",""));b.append("\n\nAndroid decide cuándo puede ejecutar la tarea (objetivo: una vez por hora, un tema por ronda). Guardar fuentes no reentrena los pesos ni garantiza que sean verdaderas.");return b.toString();}
 static String library(Context c){StringBuilder b=new StringBuilder(status(c));JSONArray docs=array(c,"docs");b.append("\n\nFuentes guardadas (más recientes primero):");for(int i=0;i<Math.min(20,docs.length());i++){JSONObject d=docs.optJSONObject(i);if(d!=null)b.append("\n\n").append(d.optString("title")).append("\n").append(d.optString("url")).append("\nConsultada: ").append(ResearchAnswer.date(d.optLong("saved")));}b.append("\n\nPara recuperar un tema sin conexión: busca en tu biblioteca …\nPara borrar: borra biblioteca web");return b.toString();}
 static synchronized void clear(Context c)throws Exception{if(!prefs(c).edit().putLong("generation",prefs(c).getLong("generation",0)+1).remove("docs").remove("topics").remove("lastQuery").remove("lastDocs").remove("depth").remove("lastRun").commit())throw new java.io.IOException("No pude borrar la biblioteca web.");}
}
